export const createAccountAction = remoteAction("accounting", "createAccountAction");
export const createJournalEntryAction = remoteAction("accounting", "createJournalEntryAction");
export const postJournalEntryAction = remoteAction("accounting", "postJournalEntryAction");
export const deleteJournalEntryAction = remoteAction("accounting", "deleteJournalEntryAction");
export const reverseJournalEntryAction = remoteAction("accounting", "reverseJournalEntryAction");
export const createPeriodAction = remoteAction("accounting", "createPeriodAction");
export const closePeriodAction = remoteAction("accounting", "closePeriodAction");
